  .z-dropdown { z-index: var(--snt-z-dropdown); }
  .z-overlay  { z-index: var(--snt-z-overlay);  }
  .z-sidebar  { z-index: var(--snt-z-sidebar);  }
  .z-modal    { z-index: var(--snt-z-modal);    }
  .z-toast    { z-index: var(--snt-z-toast);    }

  /* Motion — semantic duration / easing utilities */
  .duration-instant   { transition-duration: var(--snt-motion-duration-instant);   }
  .duration-snap      { transition-duration: var(--snt-motion-duration-snap);      }
  .duration-default   { transition-duration: var(--snt-motion-duration-default);   }
  .duration-emphasis  { transition-duration: var(--snt-motion-duration-emphasis);  }
  .duration-spatial   { transition-duration: var(--snt-motion-duration-spatial);   }
}

@keyframes toast-timer {
  from { width: 100%; }
  to   { width: 0%;   }
}

/* Drawer slide-in (200ms; none for reduced motion) */
@keyframes snt-modal-backdrop-in { from { opacity: 0; } to { opacity: 1; } }

@keyframes snt-modal-panel-in { from { opacity: 0; transform: translateY(8px) scale(0.98); } to { opacity: 1; transform: none; } }

@keyframes snt-toast-in { from { opacity: 0; transform: translateY(8px); } to { opacity: 1; transform: none; } }

@media (prefers-reduced-motion: no-preference) {
  .snt-toast { animation: snt-toast-in 180ms ease-out; }
  .snt-modal-backdrop { animation: snt-modal-backdrop-in 150ms ease-out; }
  .snt-modal-panel    { animation: snt-modal-panel-in 180ms ease-out; }
}

@keyframes snt-drawer-in-right { from { transform: translateX(100%); }  to { transform: none; } }

@keyframes snt-drawer-in-left  { from { transform: translateX(-100%); } to { transform: none; } }

@media (prefers-reduced-motion: no-preference) {
  .snt-drawer-right { animation: snt-drawer-in-right 200ms ease-out; }
  .snt-drawer-left  { animation: snt-drawer-in-left 200ms ease-out; }
}

/* Ask AI — a pill with a gradient hairline border. The border is drawn with a
   masked ::before so the inside stays the normal surface colour. At rest it is
   quiet; on hover/focus the gradient brightens and slides, and the sparkle
   twinkles (only when motion is allowed). */
.snt-ai-button {
  position: relative;
  isolation: isolate;
  border-radius: 9999px;
  background: var(--snt-surface-app);
  color: var(--snt-text-primary);
  transition: box-shadow 200ms ease, background-color 200ms ease;
}

.snt-ai-button::before {
  content: "";
  position: absolute;
  inset: 0;
  z-index: -1;
  border-radius: inherit;
  padding: 1px;
  background: linear-gradient(120deg, var(--snt-brand-primary-500), var(--snt-scale-blue-500), var(--snt-brand-primary-500));
  background-size: 250% 100%;
  -webkit-mask: linear-gradient(#000 0 0) content-box, linear-gradient(#000 0 0);
  -webkit-mask-composite: xor;
  mask: linear-gradient(#000 0 0) content-box exclude, linear-gradient(#000 0 0);
  opacity: 0.45;
  transition: opacity 200ms ease;
}

.snt-ai-button:hover,
.snt-ai-button:focus-visible {
  background: var(--snt-bg-brand-subtle);
  box-shadow: 0 0 0 4px color-mix(in srgb, var(--snt-brand-primary-500) 12%, transparent);
}

.snt-ai-button:hover::before,
.snt-ai-button:focus-visible::before {
  opacity: 1;
}

.snt-ai-button .snt-ai-icon {
  color: var(--snt-text-link);
}

@keyframes snt-ai-slide { to { background-position: 250% 0; } }

@keyframes snt-ai-twinkle {
  0%, 100% { transform: scale(1) rotate(0deg); }
  50%      { transform: scale(1.18) rotate(12deg); }
}

@media (prefers-reduced-motion: no-preference) {
  .snt-ai-button:hover::before,
  .snt-ai-button:focus-visible::before { animation: snt-ai-slide 2.4s linear infinite; }
  .snt-ai-button:hover .snt-ai-icon,
  .snt-ai-button:focus-visible .snt-ai-icon { animation: snt-ai-twinkle 1.2s ease-in-out infinite; }
}

.toast-timer-bar {
  animation: toast-timer 4s linear forwards;
}

@keyframes snt-pulse-dot {
  0%,
  100% {
    opacity: 1;
  }
  50% {
    opacity: 0.3;
  }
}

.snt-pulse-dot {
  animation: snt-pulse-dot 2s infinite;
}

@keyframes snt-gauge-draw {
  to {
    stroke-dashoffset: 0;
  }
}

.snt-scrollbar-hide {
  scrollbar-width: none;
  -ms-overflow-style: none;
}

.snt-scrollbar-hide::-webkit-scrollbar {
  display: none;
}

/* Respect the OS "reduce motion" setting (WCAG 2.3.3). */
@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
    scroll-behavior: auto !important;
  }
}
